import json
case=json.load(open('network.json')); rep=json.load(open('report.json'))
th=case['thermal_generators']; T=case['time_periods']
rep_t={g['name']:g for g in rep['thermal_generators']}
tol=1e-3
issues={'A_strict_rampup':[], 'B_strict_rampdown':[], 'C_reserve_ramp':[], 'D_r_gt_RU':[], 'E_startup_Pmin_gt_RU':[], 'F_shutdown_Pmin_gt_RD':[]}
for name,g in th.items():
    R=rep_t[name]; c,p,r=R['commitment'],R['production_MW'],R['reserve_MW']
    su_l,sd_l=R['startup'],R['shutdown']
    prev_on=g['unit_on_t0']; prev_p=g['power_output_t0']
    RU,RD=g['ramp_up_limit'],g['ramp_down_limit']
    for t in range(T):
        d_up=p[t]-prev_p; d_dn=prev_p-p[t]
        if d_up > RU+tol: issues['A_strict_rampup'].append((name,t,round(d_up,2),RU,su_l[t]))
        if d_dn > RD+tol: issues['B_strict_rampdown'].append((name,t,round(d_dn,2),RD,sd_l[t]))
        if p[t]+r[t]-prev_p > RU+tol: issues['C_reserve_ramp'].append((name,t,round(p[t]+r[t]-prev_p,2),RU,su_l[t]))
        if r[t] > RU+tol: issues['D_r_gt_RU'].append((name,t,round(r[t],2),RU))
        if su_l[t] and g['power_output_minimum'] > RU: issues['E_startup_Pmin_gt_RU'].append((name,t,g['power_output_minimum'],RU,p[t]))
        if sd_l[t] and g['power_output_minimum'] > RD: issues['F_shutdown_Pmin_gt_RD'].append((name,t,g['power_output_minimum'],RD,p[t-1] if t>0 else prev_p))
        prev_on,prev_p=c[t],p[t]
for k,v in issues.items():
    print(k, len(v), v[:8])
